import math

def is_perfect_cube(n):
    if n == 0:
        return True

    # Determine the sign and work with the absolute value
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Estimate the cube root. We use round() for precision near integers.
    # Since n is relatively small, standard float exponentiation should be okay.
    root = round(n**(1/3))

    # Check if root cubed equals n
    if root**3 == n:
        return True

    # Also check the neighbors due to potential floating point inaccuracies, 
    # though this is less necessary for small integers.
    if (root - 1)**3 == n:
        return True
    if (root + 1)**3 == n:
        return True

    return False

def check_expression(x):
    numerator = (8 * x - 41) * (x + 3)**2
    return is_perfect_cube(numerator)

solutions = []
for x in range(-15, 16):
    if check_expression(x):
        solutions.append(x)

print(solutions)

